description:
## 🌐 RealTimeMP - Real-Time Multiplayer for GDevelop 5

A complete, fully customizable real-time multiplayer extension. Connect to **any** WebSocket server — your own, a free service, or a local server.

### ✅ Features
- Connect/disconnect to **any** WebSocket server URL
- Room system: create, join, leave rooms with optional passwords
- Full **player state sync** (position, angle, custom data)
- **Room variables** shared between all players
- **Custom events** (broadcast or targeted to one player)
- **Remote Procedure Calls (RPC)** — trigger actions on other clients
- **In-game chat** system
- **Lobby list** — list all available rooms
- **Host migration** — new host assigned automatically if host leaves
- **Latency / ping** measurement per player
- **Object synchronization** — sync any game object position
- **Kick player** (host only)
- All data structures exposed as GDevelop variables

### 🛠 Setup
1. Import this extension into your GDevelop project
2. Deploy the included Node.js server (server code in the description below)
3. Use `Connect to server` action on scene start
4. Use `Join Room` or `Create Room`
5. Use `Send Player State` every frame

### 🖥 Free server options
- Run locally with Node.js
- Deploy to Railway, Render, Fly.io, or Glitch (all free tiers)

---
```javascript
// Minimal Node.js server (save as server.js, run: node server.js)
const WebSocket = require('ws');
const wss = new WebSocket.Server({ port: process.env.PORT || 8080 });
const players = new Map();
const rooms = new Map();
let playerIdCounter = 0;

function broadcast(room, msg, excludeId) {
  const r = rooms.get(room);
  if (!r) return;
  const str = JSON.stringify(msg);
  for (const pid of r.players) {
    if (pid === excludeId) continue;
    const p = players.get(pid);
    if (p && p.ws.readyState === 1) p.ws.send(str);
  }
}
function sendTo(pid, msg) {
  const p = players.get(pid);
  if (p && p.ws.readyState === 1) p.ws.send(JSON.stringify(msg));
}

wss.on('connection', (ws) => {
  const playerId = 'p' + (++playerIdCounter);
  const player = { id: playerId, name: '', room: null, ws };
  players.set(playerId, player);
  ws.send(JSON.stringify({ type: 'welcome', playerId }));

  ws.on('message', (raw) => {
    let msg; try { msg = JSON.parse(raw); } catch { return; }

    if (msg.type === 'identify') {
      player.name = msg.name || 'Player';
    }
    else if (msg.type === 'ping') {
      ws.send(JSON.stringify({ type: 'pong', t: msg.t }));
    }
    else if (msg.type === 'create_room') {
      const rid = 'room_' + Date.now();
      const room = { id: rid, name: msg.roomName || rid, host: playerId, players: new Set([playerId]), variables: {}, password: msg.password || '', maxPlayers: msg.maxPlayers || 8, isPrivate: msg.isPrivate || false };
      rooms.set(rid, room);
      player.room = rid;
      const playerData = {};
      playerData[playerId] = { name: player.name };
      ws.send(JSON.stringify({ type: 'room_joined', roomId: rid, isHost: true, players: playerData, variables: {} }));
    }
    else if (msg.type === 'join_room') {
      const room = rooms.get(msg.roomId);
      if (!room) { ws.send(JSON.stringify({ type: 'error', message: 'Room not found' })); return; }
      if (room.password && room.password !== msg.password) { ws.send(JSON.stringify({ type: 'error', message: 'Wrong password' })); return; }
      if (room.players.size >= room.maxPlayers) { ws.send(JSON.stringify({ type: 'error', message: 'Room full' })); return; }
      room.players.add(playerId);
      player.room = msg.roomId;
      const pData = {};
      for (const pid of room.players) { const p2 = players.get(pid); if (p2) pData[pid] = { name: p2.name }; }
      ws.send(JSON.stringify({ type: 'room_joined', roomId: msg.roomId, isHost: playerId === room.host, players: pData, variables: room.variables }));
      broadcast(msg.roomId, { type: 'player_joined', playerId, playerName: player.name, playerData: { name: player.name } }, playerId);
    }
    else if (msg.type === 'leave_room') {
      if (!player.room) return;
      const rid = player.room;
      const room = rooms.get(rid);
      if (room) {
        room.players.delete(playerId);
        broadcast(rid, { type: 'player_left', playerId });
        if (room.host === playerId && room.players.size > 0) {
          room.host = [...room.players][0];
          broadcast(rid, { type: 'host_changed', newHostId: room.host });
          sendTo(room.host, { type: 'host_changed', newHostId: room.host });
        }
        if (room.players.size === 0) rooms.delete(rid);
      }
      player.room = null;
      ws.send(JSON.stringify({ type: 'room_left' }));
    }
    else if (msg.type === 'player_state') {
      if (player.room) broadcast(player.room, { type: 'player_state', playerId, state: msg.state }, playerId);
    }
    else if (msg.type === 'custom_event') {
      const evtMsg = { type: 'custom_event', name: msg.name, data: msg.data, senderId: playerId };
      if (msg.target && msg.target !== '') sendTo(msg.target, evtMsg);
      else if (player.room) broadcast(player.room, evtMsg, playerId);
    }
    else if (msg.type === 'rpc') {
      const rpcMsg = { type: 'rpc', name: msg.name, args: msg.args, senderId: playerId };
      if (msg.target && msg.target !== '') sendTo(msg.target, rpcMsg);
      else if (player.room) broadcast(player.room, rpcMsg, playerId);
    }
    else if (msg.type === 'chat') {
      if (player.room) broadcast(player.room, { type: 'chat', senderId: playerId, senderName: player.name, text: msg.text }, null);
    }
    else if (msg.type === 'room_variable') {
      const room = rooms.get(player.room);
      if (room) {
        room.variables[msg.key] = msg.value;
        broadcast(player.room, { type: 'room_variable', key: msg.key, value: msg.value }, null);
      }
    }
    else if (msg.type === 'object_sync') {
      if (player.room) broadcast(player.room, { type: 'object_sync', objects: msg.objects }, playerId);
    }
    else if (msg.type === 'get_lobby') {
      const list = [];
      for (const [rid, r] of rooms.entries()) {
        if (!r.isPrivate) list.push({ id: rid, name: r.name, playerCount: r.players.size, maxPlayers: r.maxPlayers, locked: !!r.password });
      }
      ws.send(JSON.stringify({ type: 'lobby_list', rooms: list }));
    }
    else if (msg.type === 'kick') {
      const room = rooms.get(player.room);
      if (room && room.host === playerId) {
        sendTo(msg.targetId, { type: 'kicked', reason: msg.reason || '' });
        room.players.delete(msg.targetId);
        broadcast(player.room, { type: 'player_left', playerId: msg.targetId }, msg.targetId);
        const kicked = players.get(msg.targetId);
        if (kicked) { kicked.room = null; kicked.ws.close(); }
      }
    }
  });

  ws.on('close', () => {
    if (player.room) {
      const room = rooms.get(player.room);
      if (room) {
        room.players.delete(playerId);
        broadcast(player.room, { type: 'player_left', playerId });
        if (room.host === playerId && room.players.size > 0) {
          room.host = [...room.players][0];
          broadcast(player.room, { type: 'host_changed', newHostId: room.host });
        }
        if (room.players.size === 0) rooms.delete(player.room);
      }
    }
    players.delete(playerId);
  });
});
console.log('RealTimeMP server running');
```

