if (!gdjs.RealTimeMP) {
    gdjs.RealTimeMP = {
        // --- Connection state ---
        socket: null,
        serverUrl: "",
        roomId: "",
        playerId: "",
        playerName: "",
        isHost: false,
        connectionStatus: "disconnected", // disconnected | connecting | connected | error
        lastError: "",

        // --- Room state ---
        roomPlayers: {},       // { playerId: { name, x, y, angle, data, ping, latency } }
        roomVariables: {},     // { key: value }
        customEvents: [],      // [ { name, senderId, data } ]
        chatMessages: [],      // [ { senderId, senderName, text, timestamp } ]
        playerCount: 0,

        // --- Object sync ---
        syncObjects: {},       // { objectName: { x, y, angle, scaleX, scaleY, visible, animation, zOrder, data } }

        // --- RPC queue ---
        rpcQueue: [],          // [ { name, args, senderId } ]

        // --- Ping / latency ---
        pingInterval: null,
        latency: 0,
        pingSentAt: 0,

        // --- Lobby ---
        lobbyRooms: [],        // [ { id, name, playerCount, maxPlayers, locked } ]

        // --- Prediction / Reconciliation ---
        inputBuffer: [],

        // --- Timers ---
        tickInterval: null,
        syncRate: 50,  // ms

        // --- Flags ---
        justConnected: false,
        justDisconnected: false,
        justJoinedRoom: false,
        justLeftRoom: false,
        playerJustJoined: "",
        playerJustLeft: "",
        hostChanged: false,
        newHostId: "",

        // ============================================================
        _reset: function() {
            if (this.pingInterval) clearInterval(this.pingInterval);
            if (this.tickInterval) clearInterval(this.tickInterval);
            this.socket = null;
            this.connectionStatus = "disconnected";
            this.roomId = "";
            this.playerId = "";
            this.isHost = false;
            this.roomPlayers = {};
            this.roomVariables = {};
            this.customEvents = [];
            this.chatMessages = [];
            this.syncObjects = {};
            this.rpcQueue = [];
            this.lobbyRooms = [];
            this.playerCount = 0;
        },

        // ============================================================
        _send: function(msgObj) {
            if (this.socket && this.socket.readyState === WebSocket.OPEN) {
                this.socket.send(JSON.stringify(msgObj));
                return true;
            }
            return false;
        },

        // ============================================================
        _handleMessage: function(rawData) {
            let msg;
            try { msg = JSON.parse(rawData); } catch(e) { return; }
            const t = msg.type;

            if (t === "welcome") {
                this.playerId = msg.playerId;
                this.connectionStatus = "connected";
                this.justConnected = true;
                // start ping
                this.pingSentAt = Date.now();
                this._send({ type: "ping", t: this.pingSentAt });
                this.pingInterval = setInterval(() => {
                    this.pingSentAt = Date.now();
                    this._send({ type: "ping", t: this.pingSentAt });
                }, 2000);
            }
            else if (t === "pong") {
                this.latency = Math.round((Date.now() - msg.t) / 2);
                if (this.roomPlayers[this.playerId]) {
                    this.roomPlayers[this.playerId].latency = this.latency;
                }
            }
            else if (t === "room_joined") {
                this.roomId = msg.roomId;
                this.isHost = msg.isHost || false;
                this.roomPlayers = msg.players || {};
                this.roomVariables = msg.variables || {};
                this.playerCount = Object.keys(this.roomPlayers).length;
                this.justJoinedRoom = true;
            }
            else if (t === "room_left") {
                this.roomId = "";
                this.isHost = false;
                this.roomPlayers = {};
                this.roomVariables = {};
                this.playerCount = 0;
                this.justLeftRoom = true;
            }
            else if (t === "player_joined") {
                this.roomPlayers[msg.playerId] = msg.playerData || { name: msg.playerName || "", x:0, y:0, angle:0, data:{} };
                this.playerCount = Object.keys(this.roomPlayers).length;
                this.playerJustJoined = msg.playerId;
            }
            else if (t === "player_left") {
                delete this.roomPlayers[msg.playerId];
                this.playerCount = Object.keys(this.roomPlayers).length;
                this.playerJustLeft = msg.playerId;
            }
            else if (t === "host_changed") {
                this.isHost = (msg.newHostId === this.playerId);
                this.newHostId = msg.newHostId;
                this.hostChanged = true;
            }
            else if (t === "state_sync") {
                // batch sync of all players
                const states = msg.states || {};
                for (const [pid, state] of Object.entries(states)) {
                    if (!this.roomPlayers[pid]) this.roomPlayers[pid] = {};
                    Object.assign(this.roomPlayers[pid], state);
                }
            }
            else if (t === "player_state") {
                const pid = msg.playerId;
                if (!this.roomPlayers[pid]) this.roomPlayers[pid] = {};
                Object.assign(this.roomPlayers[pid], msg.state);
            }
            else if (t === "object_sync") {
                const objs = msg.objects || {};
                for (const [objId, objState] of Object.entries(objs)) {
                    this.syncObjects[objId] = objState;
                }
            }
            else if (t === "room_variable") {
                this.roomVariables[msg.key] = msg.value;
            }
            else if (t === "custom_event") {
                this.customEvents.push({ name: msg.name, senderId: msg.senderId, data: msg.data || "" });
            }
            else if (t === "rpc") {
                this.rpcQueue.push({ name: msg.name, args: msg.args || [], senderId: msg.senderId });
            }
            else if (t === "chat") {
                this.chatMessages.push({ senderId: msg.senderId, senderName: msg.senderName || "", text: msg.text, timestamp: Date.now() });
                if (this.chatMessages.length > 100) this.chatMessages.shift();
            }
            else if (t === "lobby_list") {
                this.lobbyRooms = msg.rooms || [];
            }
            else if (t === "error") {
                this.lastError = msg.message || "Unknown error";
                this.connectionStatus = "error";
            }
            else if (t === "kicked") {
                this.lastError = "Kicked: " + (msg.reason || "");
                if (this.socket) this.socket.close();
            }
        }
    };
}

const mp = gdjs.RealTimeMP;
if (!mp) return;
// Reset per-frame flags
mp.justConnected = false;
mp.justDisconnected = false;
mp.justJoinedRoom = false;
mp.justLeftRoom = false;
mp.playerJustJoined = "";
mp.playerJustLeft = "";
mp.hostChanged = false;

const mp = gdjs.RealTimeMP;
if (mp) {
    if (mp.pingInterval) clearInterval(mp.pingInterval);
    if (mp.tickInterval) clearInterval(mp.tickInterval);
    if (mp.socket) mp.socket.close();
    gdjs.RealTimeMP = null;
}

const mp = gdjs.RealTimeMP;
const url = eventsFunctionContext.getArgument("serverUrl");
const playerName = eventsFunctionContext.getArgument("playerName");

mp._reset();
mp.serverUrl = url;
mp.playerName = playerName;
mp.connectionStatus = "connecting";

mp.socket = new WebSocket(url);

mp.socket.addEventListener("open", () => {
    mp._send({ type: "identify", name: playerName });
});

mp.socket.addEventListener("message", (e) => {
    mp._handleMessage(e.data);
});

mp.socket.addEventListener("error", (e) => {
    mp.connectionStatus = "error";
    mp.lastError = "Connection error";
});

mp.socket.addEventListener("close", () => {
    mp.justDisconnected = true;
    mp.connectionStatus = "disconnected";
    if (mp.pingInterval) clearInterval(mp.pingInterval);
});

const mp = gdjs.RealTimeMP;
if (mp && mp.socket) {
    mp.socket.close(1000, "User disconnected");
}

const mp = gdjs.RealTimeMP;
const roomName = eventsFunctionContext.getArgument("roomName");
const maxPlayers = eventsFunctionContext.getArgument("maxPlayers");
const password = eventsFunctionContext.getArgument("password");
const isPrivate = eventsFunctionContext.getArgument("isPrivate") === "true" || eventsFunctionContext.getArgument("isPrivate") === true;
mp._send({ type: "create_room", roomName, maxPlayers: parseInt(maxPlayers)||8, password, isPrivate });

const mp = gdjs.RealTimeMP;
const roomId = eventsFunctionContext.getArgument("roomId");
const password = eventsFunctionContext.getArgument("password");
mp._send({ type: "join_room", roomId, password });

const mp = gdjs.RealTimeMP;
const x = eventsFunctionContext.getArgument("x");
const y = eventsFunctionContext.getArgument("y");
const angle = eventsFunctionContext.getArgument("angle");
const customData = eventsFunctionContext.getArgument("customData");
mp._send({
    type: "player_state",
    state: { x: parseFloat(x)||0, y: parseFloat(y)||0, angle: parseFloat(angle)||0, data: customData, name: mp.playerName, latency: mp.latency }
});

const mp = gdjs.RealTimeMP;
const name = eventsFunctionContext.getArgument("eventName");
const data = eventsFunctionContext.getArgument("eventData");
const target = eventsFunctionContext.getArgument("targetId"); // "" = broadcast
mp._send({ type: "custom_event", name, data, target });

const mp = gdjs.RealTimeMP;
const name = eventsFunctionContext.getArgument("rpcName");
const args = eventsFunctionContext.getArgument("argsJson");
const target = eventsFunctionContext.getArgument("targetId");
mp._send({ type: "rpc", name, args: JSON.parse(args||"[]"), target });

const mp = gdjs.RealTimeMP;
const key = eventsFunctionContext.getArgument("key");
const value = eventsFunctionContext.getArgument("value");
mp._send({ type: "room_variable", key, value });

const mp = gdjs.RealTimeMP;
const text = eventsFunctionContext.getArgument("text");
mp._send({ type: "chat", text, senderName: mp.playerName });

const mp = gdjs.RealTimeMP;
const objId = eventsFunctionContext.getArgument("objectId");
const x = parseFloat(eventsFunctionContext.getArgument("x"))||0;
const y = parseFloat(eventsFunctionContext.getArgument("y"))||0;
const angle = parseFloat(eventsFunctionContext.getArgument("angle"))||0;
const extra = eventsFunctionContext.getArgument("extraData");
mp._send({ type: "object_sync", objects: { [objId]: { x, y, angle, extra } } });

const mp = gdjs.RealTimeMP;
const pid = eventsFunctionContext.getArgument("playerId");
const reason = eventsFunctionContext.getArgument("reason");
mp._send({ type: "kick", targetId: pid, reason });
